import gurobipy as gp
from gurobipy import GRB

# Parameters
products = ['A1', 'A2', 'A3']
days = list(range(1, 23))  # 22 days

max_demand = {'A1': 5300, 'A2': 4500, 'A3': 5400}
price = {'A1': 124, 'A2': 109, 'A3': 115}
production_cost = {'A1': 73.30, 'A2': 52.90, 'A3': 65.40}
quota = {'A1': 500, 'A2': 450, 'A3': 550}
activation_cost = {'A1': 170000, 'A2': 150000, 'A3': 100000}
min_batch = {'A1': 20, 'A2': 20, 'A3': 16}

# Create model
model = gp.Model("production_plan")

# Variables
y = model.addVars(products, days, vtype=GRB.BINARY, name="y")
x = model.addVars(products, days, vtype=GRB.CONTINUOUS, name="x")
z = model.addVars(products, vtype=GRB.BINARY, name="z")

# Constraints
for i in products:
    for d in days:
        model.addConstr(x[i, d] <= quota[i] * y[i, d], name=f"x_le_{i}_{d}")
        model.addConstr(x[i, d] >= min_batch[i] * y[i, d], name=f"x_ge_{i}_{d}")

for i in products:
    model.addConstr(gp.quicksum(x[i, d] for d in days) <= max_demand[i], name=f"max_demand_{i}")
    for d in days:
        model.addConstr(z[i] >= y[i, d], name=f"z_ge_y_{i}_{d}")
    model.addConstr(z[i] <= gp.quicksum(y[i, d] for d in days), name=f"z_le_sum_y_{i}")

# Objective
objective = gp.quicksum((price[i] - production_cost[i]) * gp.quicksum(x[i, d] for d in days) for i in products) - gp.quicksum(activation_cost[i] * z[i] for i in products)
model.setObjective(objective, GRB.MAXIMIZE)

# Optimize
model.optimize()

# Output
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")

